// The extension's `tests/starknet/typed-data-scalars.test.ts`: a leaf is signable under its
// declared type only when that type can mean it, and an accepted value encodes to the felt
// starknet.js hashes. The table below was generated by running the extension's own
// `snip12Scalar` over `VALUES` for every type and revision (an accepted value's felt checked
// against starknet.js 10.8's `encodeValue`), so it pins acceptance and encoding both.

use super::tests::{accepts_json, felt};
use super::Revision;
use crate::dapp::typed_data_scalars::{snip12_scalar, Encoded};
use crate::js::json::{self, JsValue};
use serde_json::{json, Value};

fn revision(spelling: &str) -> Revision {
    if spelling == "1" {
        Revision::One
    } else {
        Revision::Zero
    }
}

fn accepts(rev: &str, ty: &str, value: Value) -> bool {
    let value = json::parse(&value.to_string()).unwrap();
    snip12_scalar(&value, ty, revision(rev)).is_some()
}

/// The smallest envelope in which one leaf decides whether the payload may be signed.
fn envelope(rev: &str, ty: &str, value: Value) -> Value {
    if rev == "1" {
        json!({
            "domain": { "name": "Bramble Test", "revision": "1" },
            "message": { "v": value },
            "primaryType": "Msg",
            "types": {
                "Msg": [{ "name": "v", "type": ty }],
                "StarknetDomain": [
                    { "name": "name", "type": "shortstring" },
                    { "name": "revision", "type": "shortstring" }
                ]
            }
        })
    } else {
        json!({
            "domain": { "name": "Bramble Test" },
            "message": { "v": value },
            "primaryType": "Msg",
            "types": {
                "Msg": [{ "name": "v", "type": ty }],
                "StarkNetDomain": [{ "name": "name", "type": "felt" }]
            }
        })
    }
}

const REVISIONS: [&str; 2] = ["0", "1"];

// "a numeric type refuses text, on both revisions".
#[test]
fn a_numeric_type_refuses_text() {
    for rev in REVISIONS {
        for ty in ["u128", "timestamp", "i128", "ContractAddress", "ClassHash"] {
            assert!(!accepts(rev, ty, json!("no fee required")));
            assert!(!accepts(rev, ty, json!("unlimited")));
            assert!(!accepts(rev, ty, json!("false")));
            assert!(accepts(rev, ty, json!("0x6e6f20666565207265717569726564")));
        }
    }
}

// "prose under a numeric type is refused at the hashing gate too".
#[test]
fn prose_under_a_numeric_type_is_refused_at_the_gate() {
    for rev in REVISIONS {
        assert!(!accepts_json(&envelope(
            rev,
            "u128",
            json!("no fee required")
        )));
        let numeric = json!("0x6e6f20666565207265717569726564");
        assert!(accepts_json(&envelope(rev, "u128", numeric)));
    }
}

// "a boolean and the string spelling of one are never interchangeable".
#[test]
fn a_boolean_and_its_string_spelling_are_never_interchangeable() {
    for rev in REVISIONS {
        assert!(accepts(rev, "bool", json!(false)));
        assert!(!accepts(rev, "bool", json!("false")));
        assert!(!accepts(rev, "bool", json!(0)));
        assert!(!accepts(rev, "felt", json!(false)));
        assert!(accepts(rev, "felt", json!("false")));
        assert!(!accepts_json(&envelope(rev, "felt", json!(false))));
    }
}

// "only unambiguous numeric text is read as a number".
#[test]
fn only_unambiguous_numeric_text_is_read_as_a_number() {
    for rev in REVISIONS {
        for accepted in [
            json!("1000"),
            json!("0x3e8"),
            json!("0x03e8"),
            json!("0X3E8"),
            json!("007"),
            json!(1000),
        ] {
            assert!(accepts(rev, "u128", accepted));
        }
        for refused in ["", "  ", " 12 ", "+12", "0b101", "0o17", "-0"] {
            assert!(!accepts(rev, "u128", json!(refused)), "{refused:?}");
            assert!(!accepts(rev, "felt", json!(refused)), "{refused:?}");
        }
        assert!(!accepts_json(&envelope(rev, "felt", json!(" 12 "))));
    }
}

// "each integer type is held to its own range".
#[test]
fn each_integer_type_is_held_to_its_own_range() {
    let u128_max = u128::MAX.to_string();
    let u128_over = "340282366920938463463374607431768211456";
    let felt_max = "3618502788666131213697322783095070105623107215331596699973092056135872020480";
    let felt_over = "3618502788666131213697322783095070105623107215331596699973092056135872020481";
    let i128_min = i128::MIN.to_string();
    let i128_under = "-170141183460469231731687303715884105729";
    let i128_max = i128::MAX.to_string();
    let i128_over = "170141183460469231731687303715884105728";
    for rev in REVISIONS {
        assert!(accepts(rev, "u128", json!(u128_max)));
        assert!(!accepts(rev, "u128", json!(u128_over)));
        assert!(accepts(rev, "timestamp", json!("0")));
        assert!(accepts(rev, "felt", json!(felt_max)));
        assert!(!accepts(rev, "felt", json!(felt_over)));
        assert!(!accepts(rev, "ContractAddress", json!(felt_over)));
        assert!(accepts(rev, "i128", json!(i128_max)));
        assert!(!accepts(rev, "i128", json!(i128_over)));
        assert!(!accepts(rev, "i128", json!(felt_max)));
    }
    assert!(accepts("1", "i128", json!(i128_min)));
    assert!(!accepts("1", "i128", json!(i128_under)));
    assert!(accepts("1", "i128", json!("-1")));
    assert!(!accepts("0", "i128", json!("-1")));
}

// "short strings stay short, printable, and ASCII".
#[test]
fn short_strings_stay_short_printable_and_ascii() {
    let thirty_one = "a".repeat(31);
    for rev in REVISIONS {
        assert!(accepts(rev, "shortstring", json!(thirty_one)));
        assert!(!accepts(
            rev,
            "shortstring",
            json!(format!("{thirty_one}a"))
        ));
        assert!(accepts(rev, "felt", json!("SN_MAIN")));
        assert!(!accepts(rev, "felt", json!("héllo")));
        assert!(!accepts(rev, "felt", json!("two\u{202e}lines")));
    }
    assert!(accepts("1", "string", json!("a".repeat(200))));
    assert!(!accepts("0", "string", json!("a".repeat(200))));
    assert!(!accepts("1", "string", json!("héllo")));
    assert!(!accepts("1", "string", json!(12)));
}

// "a selector is an entry point name or a felt, and nothing else".
#[test]
fn a_selector_is_an_entry_point_name_or_a_felt() {
    for rev in REVISIONS {
        assert!(accepts(rev, "selector", json!("transfer")));
        assert!(accepts(rev, "selector", json!("0x3e8")));
        assert!(!accepts(
            rev,
            "selector",
            json!("transfer 1 STRK to the treasury")
        ));
        assert!(!accepts(rev, "selector", json!(12)));
        assert!(!accepts(rev, "selector", json!("0x")));
    }
}

// "every accepted value carries the felt the pinned encoder produces", widened to the whole
// table: acceptance is the extension's case for case, and every felt is starknet.js's.
#[test]
fn every_value_reads_as_the_extension_reads_it() {
    let mut checked = 0;
    for (rev, ty, mask) in ACCEPTED {
        for (index, (text, flag)) in VALUES.iter().zip(mask.chars()).enumerate() {
            let value: JsValue = json::parse(text).unwrap();
            let read = snip12_scalar(&value, ty, revision(rev));
            assert_eq!(read.is_some(), flag == '1', "{rev} {ty} {text}");
            let table: &[(usize, &str)] = if ty == "selector" {
                &SELECTOR_ENCODED
            } else {
                &ENCODED
            };
            match read {
                None => {}
                Some(Encoded::ByteArray) => assert_eq!((rev, ty), ("1", "string")),
                Some(Encoded::Felt(encoded)) => {
                    let expected = table.iter().find(|(i, _)| *i == index).unwrap().1;
                    assert_eq!(encoded, felt(expected), "{rev} {ty} {text}");
                    checked += 1;
                }
            }
        }
    }
    assert!(checked > 200);
}

